"""One-shot pinned-source transformation for an isolated verification branch."""
from pathlib import Path
import hashlib
import json
import subprocess
BASE='9fffe38ddbf8fc962f2e4149298c8a2eee4625a0'
ROOT=Path.cwd()
NEW=['scripts/choices.mjs','scripts/observer-provider.mjs','references/interaction.md','examples/guided-session.md','review/INTERACTION-SOURCES.md','evals/INTERACTION-SMOKE.md','tests/guided-choices.test.mjs','tests/observer-provider.test.mjs']
TEMP=['maintenance/apply-gds-refinement.py','.github/workflows/gds-refinement-check.yml']
def git(*args): return subprocess.check_output(['git',*args],text=True).strip()
if git('rev-parse','HEAD^')!=BASE: raise SystemExit('Unexpected preparation parent')
changed=set(git('diff','--name-only',BASE,'HEAD').splitlines())
if changed!=set(NEW+TEMP): raise SystemExit(f'Unexpected preparation files: {sorted(changed ^ set(NEW+TEMP))}')
payload={p:(ROOT/p).read_bytes() for p in NEW}
for p in NEW+TEMP: (ROOT/p).unlink()
subprocess.run(['node','scripts/manifest.mjs'],check=True)
old_manifest=(ROOT/'MANIFEST.sha256').read_bytes()
records=dict(line.split('  ',1)[::-1] for line in old_manifest.decode().splitlines())
records['MANIFEST.sha256']=hashlib.sha256(old_manifest).hexdigest()
for p,data in payload.items():
 (ROOT/p).parent.mkdir(parents=True,exist_ok=True); (ROOT/p).write_bytes(data)
(ROOT/'baselines/main-9fffe38.json').write_text(json.dumps({'commit':BASE,'note':'Recognized immutable source before guided interaction and global-owner suppression. Not a runtime certification.','sha256':records},indent=2)+'\n')
def replace(p,old,new):
 file=ROOT/p; text=file.read_text()
 if text.count(old)!=1: raise SystemExit(f'Anchor mismatch in {p}: {text.count(old)}: {old[:100]}')
 file.write_text(text.replace(old,new))
def insert_after(p,old,added): replace(p,old,old+added)
def insert_heading(p,added):
 file=ROOT/p; head,sep,tail=file.read_text().partition('\n')
 if not sep: raise SystemExit(f'No heading boundary: {p}')
 file.write_text(head+'\n'+added+tail)
